// The person each event is about: the target of identity.*, the member of group.member_*.
return $input.all()
  .map((item) => item.json)
  .map((e) => ({
    event: e.type,
    personId: e.type.startsWith('group.') ? e.data?.identityId : e.target?.id,
    kind: e.data?.kind ?? 'person',
  }))
  .filter((x) => x.personId && x.kind === 'person');

// Landbright groups → Google groups: the one place that says which Google groups follow which Landbright groups
// (birthright groups from the Onboard flow and time-limited grants alike). Edit it here. Google groups not listed are
// never touched, so memberships made by hand in Google stay.
const DOMAIN = '__GOOGLE_DOMAIN__';
const GOOGLE_GROUPS = {
  Everyone: `everyone@${DOMAIN}`,
  Engineers: `engineering@${DOMAIN}`,
  Finance: `finance@${DOMAIN}`,
  'Payments On-call': `payments-oncall@${DOMAIN}`,
};
const event = $('Who').first().json.event;
return $input.all()
  .map((item) => item.json)
  // An agent's id, or someone deleted since: Read the person failed (On error: continue) and there is no person.
  .filter((p) => p.kind === 'person' && p.email)
  // Only addresses of the Google domain get an account; everyone else is Landbright's alone.
  .filter((p) => p.email.toLowerCase().endsWith(`@${DOMAIN}`))
  .map((p) => {
    const base = {
      personId: p.id,
      email: p.email.toLowerCase(),
      givenName: p.givenName,
      familyName: p.familyName,
      department: p.department ?? '',
      title: p.title ?? '',
      managerEmail: p.manager?.email ?? '',
      wanted: (p.groups ?? []).map((g) => GOOGLE_GROUPS[g.name]).filter(Boolean),
      managed: Object.values(GOOGLE_GROUPS),
      event,
    };
    // Active: their account and groups follow Landbright. Pre-hires wait for their start date (identity.activated).
    if (p.status === 'active') return { ...base, action: 'upsert', unsuspend: event === 'identity.reactivated' };
    // Deactivated: suspended and signed out of Google. A later group change of theirs changes nothing.
    if (p.status === 'deactivated' && event === 'identity.deactivated') return { ...base, action: 'suspend' };
    return { ...base, action: 'skip' };
  })
  .filter((x) => x.action !== 'skip');
